// PHASE2_FIXTURE_CORPUS: parameterized parser-coverage tests over the
// 12 real-world PDF fixtures generated by
// tests/fixtures/realworld/generate_realworld_fixtures.py. Each
// fixture's .expected.json sidecar declares the structural invariants
// this test asserts:
//
//   { "page_count": <int>,
//     "has_xref_repair": <bool>,
//     "description": <string>,
//     ... fixture-specific fields ... }
//
// Why
// ---
// The May-2026 testing-methodology audit found subsystem tests use
// synthetic ASCII / Letter-size / sRGB fixtures that don't exercise
// the parser on the messier shapes real-world PDFs take. This corpus
// closes that gap by gating every parser-affecting code change against
// 12 known-tricky inputs:
//
//   - subset-prefix-conflict TTF fonts (the "Alef bug" trigger)
//   - mixed CID encoding spans
//   - corrupt-but-recoverable xref tables
//   - rotated + mixed-page-size docs
//   - JPEG2000 + ICC OutputIntent
//   - Unicode (RTL + CJK + emoji) metadata
//   - linearized-marker hint dictionary
//   - PDF 1.5 cross-reference + object streams
//   - EmbeddedFiles attachments
//   - AcroForm with /CO calculation-order array
//
// The contract this test enforces is intentionally narrow:
// **every fixture must open via Document::open without throwing AND
// match the page_count declared in its sidecar.** Deeper assertions
// (round-trip preservation of these shapes) land in phases 3-5.

#include <gtest/gtest.h>
#include "core/Document.h"
#include "core/MuPdfContext.h"
#include "core/Page.h"

#include <QFile>
#include <QJsonDocument>
#include <QJsonObject>
#include <QString>

#include <filesystem>
#include <memory>
#include <string>
#include <vector>

namespace {

struct Sidecar {
    std::filesystem::path pdfPath;
    std::filesystem::path sidecarPath;
    int pageCount = -1;
    bool hasXrefRepair = false;
    QString description;
    QString fixtureType;
};

// Locate every <fixture>.expected.json sidecar under
// tests/fixtures/realworld/ and pair it with its same-stem .pdf.
std::vector<Sidecar> discoverFixtures() {
    std::vector<Sidecar> out;
    std::filesystem::path root = std::filesystem::path(TEST_FIXTURES_DIR)
                                 / "realworld";
    if (!std::filesystem::exists(root)) {
        return out;
    }
    for (auto& entry : std::filesystem::recursive_directory_iterator(root)) {
        if (!entry.is_regular_file()) continue;
        const auto& p = entry.path();
        // Accept files ending in ".expected.json".
        const std::string filename = p.filename().string();
        const std::string suffix = ".expected.json";
        if (filename.size() < suffix.size()) continue;
        if (filename.substr(filename.size() - suffix.size()) != suffix)
            continue;
        // Pair with the same-stem PDF.
        std::filesystem::path pdf = p.parent_path() /
            (filename.substr(0, filename.size() - suffix.size()) + ".pdf");
        if (!std::filesystem::exists(pdf)) continue;

        // Parse the sidecar via Qt's QJsonDocument (already linked).
        QFile f(QString::fromStdString(p.string()));
        if (!f.open(QIODevice::ReadOnly)) continue;
        QByteArray bytes = f.readAll();
        f.close();
        QJsonParseError err{};
        QJsonDocument doc = QJsonDocument::fromJson(bytes, &err);
        if (err.error != QJsonParseError::NoError) {
            ADD_FAILURE() << "Sidecar " << p.string()
                          << " is not valid JSON: "
                          << err.errorString().toStdString();
            continue;
        }
        QJsonObject obj = doc.object();
        Sidecar s;
        s.pdfPath = pdf;
        s.sidecarPath = p;
        s.pageCount = obj.value("page_count").toInt(-1);
        s.hasXrefRepair = obj.value("has_xref_repair").toBool(false);
        s.description = obj.value("description").toString();
        s.fixtureType = obj.value("fixture_type").toString();
        out.push_back(std::move(s));
    }
    // Stable order so test names are reproducible.
    std::sort(out.begin(), out.end(), [](const Sidecar& a, const Sidecar& b) {
        return a.pdfPath.filename() < b.pdfPath.filename();
    });
    return out;
}

class RealworldCorpusTest : public ::testing::TestWithParam<Sidecar> {
protected:
    std::shared_ptr<pdfe::core::MuPdfContext> ctx_;

    void SetUp() override {
        ctx_ = std::make_shared<pdfe::core::MuPdfContext>();
    }
};

// PHASE5: parameterized parser coverage. For every realworld
// fixture, extractText(page 0) must run to completion without
// throwing — catches parser regressions on edge-case shapes
// (subset-prefix conflicts, mixed CID encodings, JPX placeholders,
// ICC profiles, Unicode metadata, corrupt-but-recoverable xref).
// We don't assert content — the contract is "the extractor doesn't
// crash on real-world inputs".
TEST_P(RealworldCorpusTest, ExtractTextDoesNotThrowOnPageZero) {
    const Sidecar& s = GetParam();
    ASSERT_TRUE(std::filesystem::exists(s.pdfPath));

    std::unique_ptr<pdfe::core::Document> doc;
    ASSERT_NO_THROW({
        doc = pdfe::core::Document::open(ctx_, s.pdfPath);
    });
    ASSERT_NE(doc, nullptr);
    ASSERT_GE(doc->pageCount(), 1);

    auto page = doc->page(0);
    ASSERT_NE(page, nullptr);
    EXPECT_NO_THROW({
        std::string text = page->extractPlainText();
        // The text result IS allowed to be empty on, e.g.,
        // jpeg2000_image.pdf (image-only) or icc_outputintent.pdf
        // (no content stream). What matters is the call returned
        // without throwing.
        (void)text;
    }) << "extractPlainText must not throw on realworld fixture "
       << s.pdfPath.filename().string()
       << " (" << s.fixtureType.toStdString() << ")";
}

TEST_P(RealworldCorpusTest, OpensAndMatchesSidecarPageCount) {
    const Sidecar& s = GetParam();
    ASSERT_TRUE(std::filesystem::exists(s.pdfPath))
        << "Fixture PDF missing: " << s.pdfPath.string();

    // The sidecar is the test oracle. Each field below has a real
    // structural contract — none are advisory.
    ASSERT_GE(s.pageCount, 1)
        << "Sidecar declares page_count < 1 for "
        << s.pdfPath.filename().string();
    ASSERT_FALSE(s.description.isEmpty())
        << "Sidecar must include a non-empty description";
    ASSERT_FALSE(s.fixtureType.isEmpty())
        << "Sidecar must include a fixture_type identifier";

    // The corpus contract: Document::open must not throw on any of
    // these inputs, even the deliberately-malformed ones (corrupt
    // xref, JPX-placeholder, ICC placeholder). MuPDF's recovery
    // paths are part of the parser surface this corpus exercises.
    std::unique_ptr<pdfe::core::Document> doc;
    ASSERT_NO_THROW({
        doc = pdfe::core::Document::open(ctx_, s.pdfPath);
    }) << "Document::open threw on "
       << s.pdfPath.filename().string()
       << " (description: " << s.description.toStdString() << ")";
    ASSERT_NE(doc, nullptr)
        << "Document::open returned null for "
        << s.pdfPath.filename().string();

    // Page count must match the sidecar exactly. Drift here means
    // either the parser is dropping pages or the fixture generator
    // produced something different from what the sidecar claims —
    // both are bugs worth surfacing.
    EXPECT_EQ(doc->pageCount(), s.pageCount)
        << "page_count mismatch on "
        << s.pdfPath.filename().string()
        << " (sidecar expected " << s.pageCount
        << ", parser reports " << doc->pageCount() << ")";
}

INSTANTIATE_TEST_SUITE_P(
    RealworldFixtures,
    RealworldCorpusTest,
    ::testing::ValuesIn(discoverFixtures()),
    [](const ::testing::TestParamInfo<Sidecar>& info) {
        // GoogleTest test names must be valid C++ identifiers, so
        // turn "rotated_mixed.pdf" into "rotated_mixed_pdf" etc.
        std::string name = info.param.pdfPath.filename().string();
        for (char& c : name) {
            if (!std::isalnum(static_cast<unsigned char>(c))) c = '_';
        }
        return name;
    });

// Top-level sanity: confirm at least 12 fixtures were discovered. If
// the count drops, the corpus has eroded and the parameterized tests
// above silently cover less ground.
TEST(RealworldCorpusInventoryTest, AtLeastTwelveFixtures) {
    auto fixtures = discoverFixtures();
    ASSERT_GE(fixtures.size(), 12u)
        << "Phase-2 contract requires >= 12 real-world fixtures; got "
        << fixtures.size() << ". Re-run "
        << "tests/fixtures/realworld/generate_realworld_fixtures.py "
        << "to regenerate.";
}

} // namespace
